// Record of generated files.

import { existsSync, lstatSync, readFileSync, renameSync, rmSync, writeFileSync } from "node:fs";
import path from "node:path";

////////////////////////////////
//  Interfaces & Types

export type ManifestList = "contract" | "cases";

type Lists = Record<ManifestList, string[]>;

////////////////////////////////
//  Constants

export const MANIFEST = "parity.generated.json";

const LISTS: ManifestList[] = ["contract", "cases"];

////////////////////////////////
//  Functions & Helpers

function checkEntry(root: string, entry: string): void {
	const relative = path.relative(root, path.resolve(root, entry));
	const outside = relative === ".." || relative.startsWith(`..${path.sep}`) || path.isAbsolute(relative);
	if (entry === "" || outside) {
		throw new Error(`${MANIFEST} names ${JSON.stringify(entry)}, outside the project`);
	}
	if (entry.includes("\\")) throw new Error(`${MANIFEST} names ${JSON.stringify(entry)}, which holds a backslash`);
	if (entry === MANIFEST) throw new Error(`${MANIFEST} lists itself`);
	if (entry === "." || entry.endsWith("/") || path.posix.normalize(entry) !== entry) {
		throw new Error(`${MANIFEST} names ${JSON.stringify(entry)}, which is no normalized file path`);
	}
}

function readLists(root: string): Lists {
	const lists: Lists = { contract: [], cases: [] };
	const file = path.join(root, MANIFEST);
	if (!existsSync(file)) return lists;
	let held: unknown;
	try {
		held = JSON.parse(readFileSync(file, "utf8"));
	} catch (error) {
		throw new Error(`${MANIFEST} is no JSON: ${error instanceof Error ? error.message : error}`);
	}
	const object = (held ?? {}) as Record<string, unknown>;
	for (const name of LISTS) {
		const paths = object[name] ?? [];
		if (!Array.isArray(paths) || paths.some((entry) => typeof entry !== "string")) {
			throw new Error(`${MANIFEST} holds no list of paths under ${name}`);
		}
		for (const entry of paths as string[]) checkEntry(root, entry);
		lists[name] = paths as string[];
	}
	const twice = lists.contract.find((entry) => lists.cases.includes(entry));
	if (twice !== undefined) throw new Error(`${MANIFEST} lists ${JSON.stringify(twice)} twice`);
	return lists;
}

/** What the last refresh generated. */
export const recorded = (root: string, name: ManifestList): string[] => readLists(root)[name];

const sortedPaths = (paths: Iterable<string>): string[] => [...paths].sort((left, right) => (left < right ? -1 : 1));

/** Drift of a list against the fresh paths. */
export function manifestProblems(root: string, name: ManifestList, fresh: Iterable<string>): string[] {
	const now = sortedPaths(fresh);
	const old = recorded(root, name);
	const problems = old.filter((file) => !now.includes(file)).map((file) => `${file} is generated by nothing`);
	if (now.length !== old.length || now.some((file, at) => file !== old[at])) {
		problems.push(`${MANIFEST} is stale`);
	}
	return problems;
}

/** Removes what the last refresh generated and the fresh set lacks. */
export function removeStale(root: string, name: ManifestList, fresh: Iterable<string>): void {
	const now = new Set(fresh);
	for (const file of recorded(root, name)) {
		if (now.has(file)) continue;
		const parts = file.split("/");
		let at = root;
		for (const part of parts.slice(0, -1)) {
			at = path.join(at, part);
			const held = lstatSync(at, { throwIfNoEntry: false });
			if (!held) break;
			if (held.isSymbolicLink()) throw new Error(`${MANIFEST} names ${file}, behind a link at ${part}`);
		}
		const target = path.join(root, file);
		if (lstatSync(target, { throwIfNoEntry: false })?.isFile()) rmSync(target);
	}
}

/** Rewrites one list; the other stays. */
export function writeList(root: string, name: ManifestList, fresh: Iterable<string>): void {
	const lists = readLists(root);
	lists[name] = sortedPaths(fresh);
	const text = JSON.stringify({ contract: sortedPaths(lists.contract), cases: sortedPaths(lists.cases) }, null, "\t");
	const temp = path.join(root, `${MANIFEST}.${process.pid}.tmp`);
	writeFileSync(temp, `${text}\n`);
	renameSync(temp, path.join(root, MANIFEST));
}
